// Every provider's own category tree, generated by backend/scripts/syncProviderCategories.ts. Loaded only when the
// mapping is edited: it's large, MyMiniFactory's alone near a thousand.

export type CatalogEntry = { id: string; name: string; parent: string | null };
export type Catalog = Record<string, CatalogEntry[]>;

/** One of a provider's categories, with where it sits: its top-level category, and its names from the top. */
export type CatalogCategory = CatalogEntry & { root: string; path: string[] };

let loading: Promise<Catalog> | null = null;

export function loadProviderCatalog(): Promise<Catalog> {
  loading ??= import("./providerCategories.json").then((module) => module.default as Catalog);
  return loading;
}

/** A provider's categories by id, each knowing its top-level category and path. */
export function indexCatalog(entries: CatalogEntry[]): Map<string, CatalogCategory> {
  const byId = new Map(entries.map((entry) => [entry.id, entry]));
  const index = new Map<string, CatalogCategory>();
  for (const entry of entries) {
    const path: string[] = [];
    let current: CatalogEntry | undefined = entry;
    let root = entry.id;
    // Guards against a loop in the data, which would never end.
    for (let depth = 0; current && depth < 10; depth++) {
      path.unshift(current.name);
      root = current.id;
      current = current.parent ? byId.get(current.parent) : undefined;
    }
    index.set(entry.id, { ...entry, root, path });
  }
  return index;
}

/** The stored form, "800;71;1001" (or Thangs' category paths), as ids. */
export function splitCatIds(value: string): string[] {
  return [
    ...new Set(
      value
        .split(";")
        .map((id) => id.trim())
        .filter(Boolean),
    ),
  ];
}

export function joinCatIds(ids: string[]): string {
  return ids.join(";");
}
